<?php
echo '<div class="page-head"><div><h1>Transaction Corrections</h1><p>Request a reversal, review its stock effect and obtain Admin approval. Original records stay in history.</p></div></div>';
if(empty($_GET['request_id'])&&can_action('reversal_request'))echo '<div class="card"><h3>Request Reversal</h3><p>Use the internal batch ID from the transaction detail page. Borrowed issues are returned or converted from their linked record. Beginning-balance discrepancies use a reviewed inventory count; locked original evidence remains preserved.</p><form method="post" action="actions.php" class="inline-form"><input type="hidden" name="action" value="reversal_request"><input type="hidden" name="return" value="corrections"><label>Transaction Type<select name="source_type"><option>Inflow</option><option>Outflow</option><option>Manual Outflow</option><option>Return</option><option>Non-Sellable</option><option>Non-Sellable Release</option><option>Stock Transfer</option><option>Inventory Count</option><option>Packaging Completion</option><option>Repackaging Batch</option></select></label><label>Batch / Record ID<input type="number" name="source_id" min="1" step="1" required></label><label>Reason<textarea name="reason" required></textarea></label><button class="btn secondary">Request Reversal Review</button></form></div>';
$offset=max(0,(int)($_GET['offset']??0));$rows=db()->query('SELECT r.*,u.name requested_name,a.name approved_name FROM transaction_reversals r LEFT JOIN users u ON u.id=r.requested_by LEFT JOIN users a ON a.id=r.approved_by '.(!empty($_GET['request_id'])?'WHERE r.id='.(int)$_GET['request_id'].' ':'').'ORDER BY r.id DESC LIMIT 51 OFFSET '.$offset)->fetchAll();$more=count($rows)>50;echo '<div class="card table-wrap"><h3>Correction Requests</h3><table class="table"><tr><th>Reference / Date</th><th>Original Transaction</th><th>Reason / Requested By</th><th>Stock Effect</th><th>Status / Approval</th></tr>';foreach(array_slice($rows,0,50) as $r){$plan=json_decode($r['result_json'],true)?:[];echo '<tr><td>REV-'.$r['id'].'<br>'.e($r['created_at']).'</td><td>'.e($r['source_type']).' #'.$r['source_id'].'<br>'.e($plan['reference']??'').'</td><td>'.e($r['reason']).'<br>'.e($r['requested_name']).'</td><td>';foreach($plan['platforms']??[] as $move){$p=stock_row($move['pid']);echo e($p['name']??'Archived Product').' · '.e($move['platform']).': '.($move['delta']>0?'+':'').$move['delta'].' pcs<br>';}foreach($plan['nonsellable_outflows']??[] as $ns)echo 'Non-Sellable: +'.(int)$ns['qty'].' pcs<br>';foreach($plan['non_sellable']??[] as $ns)echo 'Non-Sellable: -'.(int)$ns['qty'].' pcs<br>';echo '</td><td>'.e($r['status']).'<br>'.e($r['approved_name']).'<br>'.e($r['approved_at']);if($r['status']==='Pending'&&current_user()['role']==='Admin')echo '<form method="post" action="actions.php" class="stack" data-confirm="Approve this reversal? The displayed inverse stock movements will be posted once; original records remain in history."><input type="hidden" name="action" value="reversal_approve"><input type="hidden" name="request_id" value="'.$r['id'].'"><input type="hidden" name="return" value="corrections"><label class="ack"><input type="checkbox" name="review_ack" value="1" required> I reviewed the original transaction, linked returns and reversal quantities.</label><button class="btn primary sm">Approve Reversal</button></form><form method="post" action="actions.php" class="stack"><input type="hidden" name="action" value="reversal_reject"><input type="hidden" name="request_id" value="'.$r['id'].'"><input type="hidden" name="return" value="corrections"><input name="reason" placeholder="Reason for rejection" required><button class="btn ghost sm">Reject Request</button></form>';echo '</td></tr>';}if(!$rows)echo '<tr><td colspan="5">No correction requests.</td></tr>';echo '</table>';if($offset)echo '<a class="btn ghost" href="?page=corrections&offset='.max(0,$offset-50).'">Previous</a>';if($more)echo '<a class="btn ghost" href="?page=corrections&offset='.($offset+50).'">Next</a>';echo '</div>';
